    {
      "path": "cordis.patch.yml",
      "content": "# dsh-plugin-wallpaper-engine bundle patch.\n#\n# Applied over the dsh-web-app layer. This bundle contributes EIGHT host rows:\n#   - four owned by the main package: the plugin that scans Wallpaper Engine and\n#     serves its media, the `about-notice` component row that owns the About tab's\n#     two routes, the `mascot-avatar` component row that owns the mascot image +\n#     the two session avatars, and the `media-bridge` component row that owns the\n#     system media integration;\n#   - three owned by `packages/{fx,parallax,fonts}`: the subpackages this main\n#     package depends on (BUNDLE-SPLIT §7.1). Semantics A (§2.3) — the main package\n#     owns these rows, each `name` is the subpackage's REAL package name, and this\n#     patch is the single source of truth for the row set; a subpackage's own\n#     cordis.patch.yml only takes effect when that subpackage is installed as a\n#     standalone bundle (not the shape used here).\n# The main package relies on its `dsh.client` manifest (in package.json) to load the\n# browser half that draws the wallpaper behind the DSH GUI and adds the settings UI.\n#\n# A patch replaces the targeted row's whole `config`, so only additive\n# `insert` rows appear here (we never override an existing shipped row).\n\n- insert:\n    # Host half: discovers the local Wallpaper Engine install (Steam app 431960),\n    # enumerates Scene/Video/Web wallpapers from the Workshop + default projects\n    # (Application wallpapers are listed but never rendered),\n    # and serves their media + a JSON inventory over same-origin HTTP routes\n    # the browser half fetches directly (GET /wallpaper-engine/inventory, /media,\n    # /preview, …; docs/ROUTE-INDEX.md is the authoritative table — it is generated\n    # and machine-checked, so the route count is deliberately not repeated here).\n    - id: wallpaper-engine\n      name: 'dsh-plugin-wallpaper-engine'\n    # Second row: the `about-notice` component's host half (C8′, P2-1). The host\n    # loads it as its own plugin — its entry re-enters this bundle's\n    # `applyComponent` — so disabling just this row removes the About tab's\n    # /star-count + /about-qr routes and leaves the other 40 untouched.\n    # P-F (2026-10-16): this component moved out to `packages/about-notice/`, so the\n    # row `name` is now the real package name (resolved through <profile>/node_modules,\n    # same as the fx / parallax / fonts rows below). The `id` is frozen.\n    - id: wallpaper-engine-about-notice\n      name: 'dsh-plugin-wallpaper-engine-about-notice'\n    # Third row: the `mascot-avatar` component's host half (C6, P2-2) — the custom\n    # mascot image (/mascot) and the two session avatars (/avatar/<side>). Same\n    # shape as the row above (independent plugin, re-enters `applyComponent`);\n    # disabling it removes just those two routes.\n    # P-F (2026-10-16): this component moved out to `packages/mascot-avatar/`, so the\n    # row `name` is now the real package name (resolved through <profile>/node_modules,\n    # same as the fx / parallax / fonts rows below). The `id` is frozen.\n    - id: wallpaper-engine-mascot-avatar\n      name: 'dsh-plugin-wallpaper-engine-mascot-avatar'\n    # Fourth row: the `media-bridge` component's host half (third component) — the\n    # system media integration (now playing / spectrum / artwork / reverse control)\n    # and its backend (the media-bridge child process with the built-in fallback).\n    # Same shape as the rows above (independent plugin, re-enters `applyComponent`);\n    # disabling it removes just those five routes. Default ON: turning it off loses\n    # the media integration (user-visible), so the row ships enabled and the user\n    # turns it off per-row if they do not want it.\n    # P-F (2026-10-16): this component moved out to `packages/media-bridge/`, so the\n    # row `name` is now the real package name (resolved through <profile>/node_modules,\n    # same as the fx / parallax / fonts rows below). The `id` is frozen.\n    - id: wallpaper-engine-media-bridge\n      name: 'dsh-plugin-wallpaper-engine-media-bridge'\n      # webServer is a hard dependency (`inject = ['webServer']` in lib/index.js):\n      # the Loader waits for the HTTP server to mount, so a headless/TUI profile\n      # without one does not load this bundle at all.\n    # ── P-A 子包行（BUNDLE-SPLIT §7.1）────────────────────────────────────────────\n    # 行的 name 是**子包的真名**（不是主包的子路径）：开发期解析靠\n    # `scripts/dev-link-subpackages.mjs` 在 <profile>/node_modules 下建的目录 junction，\n    # 与发布期 pnpm hoist 布局同形（§8.1 spike 结论）。主包 apply 会先 resolve 这三行，\n    # 解析不到就**大声抛错**（宿主对行级失败是静默的 —— §4.1 I5）。\n    # 可选桌宠联动；没有 dsh-pet 或首次准备未完成时保留吉祥物原生行为。\n    - id: wallpaper-engine-pet-link\n      name: 'dsh-plugin-wallpaper-engine-pet-link'\n    # fx：点击拖尾 + 特效扩展（src/fx-layer.js、src/ext-fx.js），浏览器半边在本包自己的产物里。\n    - id: wallpaper-engine-fx\n      name: 'dsh-plugin-wallpaper-engine-fx'\n    # parallax：3D 视差层（src/parallax-layer.js、src/ext-parallax.js），同上。\n    - id: wallpaper-engine-parallax\n      name: 'dsh-plugin-wallpaper-engine-parallax'\n    # fonts：整个字体系统（P-C 之后宿主半边 + 浏览器半边都在本包）\n    #   · 宿主半边：lib/routes/fontsets.js、lib/routes/system-fonts.js 两条路由族；\n    #   · 浏览器半边：外观页签第六节「全局字体」+ 字体集编辑器 ⇒ 产物 lib/client.fonts.js。\n    # 注意（§6.1 = A / ADR-0013 D20）：随包走的只是**渲染器与描述符**；字体的键、默认值、\n    # 消毒与持久化仍在主包 lib/settings-schema.js（FONTSET_KEYS）与 fontsets/<id>.json。\n    - id: wallpaper-engine-fonts\n      name: 'dsh-plugin-wallpaper-engine-fonts'\n    # ── 内置桌宠本体：已解耦（2026-10-20）────────────────────────────────────────\n    # `packages/pet`（`dsh-we-pet-builtin`）与它的 `wallpaper-engine-pet` 行**已从本包移除**：\n    # 它把 `electron`（optional）带进安装树，而 electron 42+ 在缺少 `dist/` 时会在\n    # `require('electron')` 里**同步**下载约 140MB 二进制 ⇒ 宿主启动被堵到 60 秒超时，\n    # 整个 profile 起不来。桌宠本体的正式接入等上游 dsh-pet 提供联动接口后，由 pet-link 对接\n    # **外部** provider；在那之前 pet-link 的就绪面如实返回 unavailable（不静默假装可用）。\n"
    },
