    {
      "path": "lib/media-origin.js",
      "content": "/**\n * 壁纸媒体源（独立 loopback 监听）＋ 适配器形态观测。\n *\n * 本模块把这批状态收进一个**显式依赖**的工厂。这批状态（媒体 token 与媒体源地址）**必须与\n * `/inventory` 同作用域** —— 扫描链与路由都要用它，是门面无法收缩的主要单点耦合。调用方在\n * `apply()` 里构建一次，拿回访问器供扫描链、`/inventory`、`/settings`、诊断族与场景载荷族共用。\n *\n * 纪律：`mediaOrigin` 与 `mediaDiagHandler` 都是**本模块的可变量**（前者懒启动、\n * 后者由 `registerDiagRoutes` 的出参稍后武装），所以跨模块**只以访问器形式**提供 ——\n * 把 `mediaOrigin.port` 的值拷进 context 会永远报 null（`/inventory` 只需要\n * `mediaOriginBase()`；端口只有诊断路由用）。\n */\nimport { createServer } from 'node:http';\nimport { ADAPTER_TARGET_VALUES } from './settings-schema.js';\n\n/**\n * @param {object} deps\n * @param {string} deps.base               请求前缀（`BASE`）。\n * @param {import('./log.js').LogFn} deps.log 宿主日志（本模块**用全形状**：会直接调 `log.error(...)`）。\n * @param {Function} deps.notice           提示通道（成功事实不写日志，走这里）。\n * @param {Function} deps.appendDiagLine   诊断环写入。\n * @param {Array} deps.disposers           卸载回卷登记表（媒体源关闭钩子推进去）。\n * @param {Function} deps.handleSceneFiles `/scene-files` 处理函数（媒体源复用同一段逻辑）。\n * @param {Function} deps.readSettings     读设置（`adapterTarget` 手选值）。\n */\nexport function createMediaOrigin({ base, log, notice, appendDiagLine, disposers, handleSceneFiles, readSettings }) {\n  // ---------------------------------------------------------------------------\n  // 3c-0. 适配器：宿主形态观测（判定与操作系统无关 —— 只读请求头与 UA）。\n  //\n  // 三档的事实来源：\n  //   · 能力头 `x-dsh-desktop-renderer` ⇒ 带栅栏的桌面端。该头由**社区壳**\n  //     注入（DSH Desktop.app 的 desktop-browser-access 分片）；官方\n  //     DeepSeek Harness.app 的 app.asar 里该字面量零命中 —— 所以\"有栅栏\"判给\n  //     社区端，而不是按 app 名望文生义。\n  //   · UA 含 `Electron/` ⇒ 桌面壳。官方与社区都是 Electron，这一档只负责把\n  //     「桌面壳」与「原生浏览器」分开，分不了官民。\n  //   · 两者皆无 ⇒ 原生浏览器。\n  // 两把闩锁**只增不减**：首帧之前可能先来一条非渲染器请求（探活、命令行），\n  // 它不该把已经判明的桌面端改回浏览器 —— 而错判成浏览器的代价是网页壁纸 403。\n  // 手选（settings.adapterTarget，见 lib/settings-schema.js）优先于观测。\n  // ---------------------------------------------------------------------------\n  let adapterFenceSeen = false;\n  let adapterShellSeen = false;\n  let adapterOverride = 'auto';\n  function observeAdapter(req) {\n    const headers = (req && req.headers) || {};\n    if (headers['x-dsh-desktop-renderer'] !== undefined) adapterFenceSeen = true;\n    const ua = headers['user-agent'];\n    if (typeof ua === 'string' && /Electron\\//i.test(ua)) adapterShellSeen = true;\n    const s = readSettings();\n    const picked = s && typeof s.adapterTarget === 'string' ? s.adapterTarget : 'auto';\n    adapterOverride = ADAPTER_TARGET_VALUES.includes(picked) ? picked : 'auto';\n  }\n  /** 观测目标（与客户端 src/adapter.js 的判定表同一套字面量）。 */\n  function adapterDetectedTarget() {\n    if (adapterFenceSeen) return 'desktop-community';\n    if (adapterShellSeen) return 'desktop-official';\n    return 'browser';\n  }\n  /** `/settings` 的 `adapter` 段：观测到的形态 + 手选后的生效值。 */\n  function adapterState() {\n    return {\n      detected: adapterDetectedTarget(),\n      fence: adapterFenceSeen,\n      target: adapterOverride !== 'auto' ? adapterOverride : adapterDetectedTarget(),\n    };\n  }\n  /** 网页壁纸载荷要不要走独立媒体源。`/media-origin` 是显式探测，不经这条。 */\n  function mediaOriginNeeded() {\n    if (adapterOverride === 'browser') return false;  // 手选浏览器：显式走应用源\n    if (adapterOverride !== 'auto') return true;      // 手选桌面：恒走独立源\n    return adapterFenceSeen || adapterShellSeen;      // 自动：观测到桌面形态才需要\n  }\n\n  // 3c-3a. 壁纸媒体源：独立 loopback 监听（壁纸载荷的落点）。\n  //\n  // 为什么需要第二个源 —— DSH Desktop 给**每一个**插件路由套了能力头栅栏\n  //（desktop-browser-access 分片 → decideDesktopBrowserAccess：请求必须带\n  // x-dsh-desktop-renderer，而该头只由 Electron 主进程注入给「frame.origin === 应用源\n  // 且顶层 frame 同源」的请求）。网页壁纸按设计必须跑在 sandbox=\"allow-scripts\" 的\n  // 不透明源里：它的 frame.origin 是 \"null\"，永远拿不到这个头 —— 于是入口 HTML 一律\n  // 403 Forbidden，服务端连一行请求日志都不会有（表现为预览图先正常、随后整块黑掉）。\n  // 增强模式下普通浏览器访问也不可用（desktopBrowserAccessAvailable 只认兼容模式），\n  // 唯一干净的出路是让壁纸载荷根本不经过宿主插件路由：我们自己在 127.0.0.1 上再监听\n  // 一个随机端口，只服务 /scene-files/<token>/…，行为与同源那条完全一致（同一段处理\n  // 函数：两层目录围栏 / CORS / shim+seed 注入 / Range）。顺带的好处是第三方 HTML 连\n  // 「同源」都不再沾边，沙箱之外又多一层隔离。\n  // **场景壁纸也走这条**：100–336MB 的 `scene.pkg` 走应用源那条路挤不过\n  // 首帧预算（15 秒里还要买纹理解码与 shader 编译），把它的载荷也指向自建源即可。\n  // 这条源的根路径 `/diag` 也要接（渲染页的诊断信标打的是 `{mediaBase origin}/diag`），\n  // 否则 mediaBase 一指过来，渲染页的告警就 404 静默丢掉 —— 见下面的 `mediaDiagHandler`。\n  let mediaOrigin = null;       // { server, port, base }\n  let mediaOriginTask = null;\n  let mediaOriginDead = false;  // 起过一次就不反复试（否则每次 inventory 都重试绑定）\n  /**\n   * 诊断族的根路径处理器（`routes/diag.js` 的 `handleDiag`），由 `registerDiagRoutes` 的**出参**\n   * `onHandleDiag`（3c-7）武装。**为什么是一个可变量而不是常量**：媒体源（3c-3a）先创建、\n   * 诊断族（3c-7）随后注册，两者在同一次 `apply` 内先后发生；而这个闭包只在**请求时**读它\n   * （媒体源是按需懒启动的，任何请求都晚于 `apply` 返回）⇒ 读到的一定是已武装的值。\n   * 传值会把 null 快照带进闭包。\n   */\n  let mediaDiagHandler = null;\n  function mediaOriginBase() {\n    // 适配器门控：**网页壁纸**的独立源只为「能力头栅栏」存在（栅栏只在桌面壳里）。\n    // 原生浏览器没有栅栏 ⇒ 网页载荷走应用源相对路径即可，不必多开一个 loopback 监听。\n    // 观测与手选都由 observeAdapter 收敛到 mediaOriginNeeded（见 3c-0）。\n    // ⚠️ **场景载荷不走这条门控**（见 ensureSceneMediaOrigin）：它要独立源的理由是带宽。\n    if (!mediaOriginNeeded()) return Promise.resolve('');\n    return ensureMediaOrigin().then((m) => (m ? m.base : ''));\n  }\n  /**\n   * 场景载荷的源（`/inventory` 的 `sceneMediaBase`）。\n   *\n   * **与适配器形态无关**：`scene.pkg` 动辄 100–336MB，走应用源（DSH 的插件路由）那条路\n   * 实测会饿死（同一份 336MB 包，应用源上出现 15–74s 甚至永不返回的传输；媒体源上 0.6s），\n   * 而首帧预算是墙钟 15s ⇒ 大场景壁纸被误判成\"渲染不出来\"并写进全局失败记忆。\n   * 带宽是**所有形态**都成立的物理约束，所以这里直接懒起媒体源（仍然只在库里真有\n   * `sceneLive` 时调用，且失败返空串回落应用源）。\n   */\n  function ensureSceneMediaOrigin() {\n    return ensureMediaOrigin().then((m) => (m ? m.base : ''));\n  }\n  function ensureMediaOrigin() {\n    if (mediaOrigin) return Promise.resolve(mediaOrigin);\n    if (mediaOriginDead) return Promise.resolve(null);\n    if (mediaOriginTask) return mediaOriginTask;\n    mediaOriginTask = new Promise((done) => {\n      const unavailable = (cause) => {\n        const msg = cause instanceof Error ? cause.message : String(cause);\n        // error：这不是优雅降级 —— 网页壁纸在 Desktop 上会直接 403（`ensureMediaOrigin`\n        // 上方那段注释说明了能力头栅栏），也就是该形态的核心能力不可用。\n        log.error(`壁纸媒体源不可用（网页壁纸回落应用源；Desktop 上会 403）：${msg}`);\n        appendDiagLine('media-origin', { base: null, error: msg.slice(0, 160) });\n        mediaOriginTask = null;\n        mediaOriginDead = true;\n        done(null);\n      };\n      let server;\n      try {\n        server = createServer((req, res) => {\n          let pathname;\n          try { pathname = new URL(req.url || '/', 'http://x').pathname; } catch { pathname = ''; }\n          // 渲染页的诊断信标打的是 `{mediaBase origin}/diag`（**根路径**，见 routes/diag.js 的\n          // Kg()）。场景壁纸的 mediaBase 指向本媒体源之后，这个根路径必须在这里也有落点 ——\n          // 否则「大场景 pkg 首帧超时」时渲染页的告警会以 404 **静默丢掉**，而那正是排查现场\n          // 唯一的内窗（同一条不变量见 routes/diag.js）。\n          // 纪律与 /scene-files 一致：**同一个 handleDiag**，不另起一份缓冲（`/diag-log` 读的是\n          // 同一份）；`${base}/diag` 一并接上，与 app 源的两条通道保持对称。\n          if (pathname === '/diag' || pathname === `${base}/diag`) {\n            // 未武装只可能发生在启动竞态里；此时**不假装成功** —— 落到下面的 404，\n            // 让\"告警丢了\"当场可见，而不是被一个 204 吞掉。\n            if (mediaDiagHandler) { mediaDiagHandler(req, res); return; }\n          }\n          if (!pathname.startsWith(`${base}/scene-files/`)) {\n            res.statusCode = 404;\n            res.setHeader('Content-Type', 'text/plain; charset=utf-8');\n            res.setHeader('Cache-Control', 'no-store');\n            res.end('not found');\n            return;\n          }\n          handleSceneFiles(req, res, 'media');\n        });\n      } catch (cause) { unavailable(cause); return; }\n      server.on('clientError', (_err, socket) => { try { socket.destroy(); } catch { /* ignore */ } });\n      server.on('error', unavailable);\n      server.listen(0, '127.0.0.1', () => {\n        const addr = server.address();\n        const port = addr && typeof addr === 'object' ? addr.port : 0;\n        if (!port) { unavailable(new Error('listen 未返回端口')); return; }\n        mediaOrigin = { server, port, base: `http://127.0.0.1:${port}` };\n        appendDiagLine('media-origin', { base: mediaOrigin.base });\n        // 成功事实：**不发日志**，只走提示通道（D4）。文案惰性构造 —— 闸门关掉时不必拼。\n        notice('media-origin', () => `壁纸媒体源已监听 ${mediaOrigin.base}（网页壁纸载荷不再经过插件路由的能力头栅栏）`);\n        done(mediaOrigin);\n      });\n    });\n    return mediaOriginTask;\n  }\n  disposers.push(() => { try { mediaOrigin?.server?.close(); } catch { /* ignore */ } });\n\n  /**\n   * `/media-origin` 的应答体：媒体源地址与端口。\n   * `mediaOrigin` 是**本作用域的可变量**（ensureMediaOrigin 会重新赋值它）⇒ 跨模块只能以\n   * **访问器**形式提供；把 `mediaOrigin.port` 的值拷进 context 会永远报 null。\n   * `/inventory` 只需要 `mediaOriginBase()`（拼 media/preview 前缀），端口只有诊断路由用。\n   */\n  function mediaOriginInfo() {\n    // 显式探测（GET /media-origin）：问的就是\"媒体源在不在\"，所以绕开适配器\n    // 门控直接起 —— 浏览器形态下 inventory 不用它，但这条诊断路由必须给真话。\n    return ensureMediaOrigin().then((m) => ({ base: (m && m.base) || null, port: mediaOrigin ? mediaOrigin.port : null }));\n  }\n\n  return {\n    observeAdapter,\n    adapterState,\n    mediaOriginBase,\n    ensureSceneMediaOrigin,\n    mediaOriginInfo,\n    /** 由 `registerDiagRoutes` 的出参武装（3c-7）。 */\n    setDiagHandler: (fn) => { mediaDiagHandler = fn; },\n  };\n}\n"
    },
    {
      "path": "lib/routes/scene-serve.js",
      "content": "/**\n * routes/scene-serve.js — **场景载荷服务族**路由：live 渲染页（`/scene-live`）、壁纸自有文件\n * （`/scene-files`）与媒体源诊断（`/media-origin`）。\n *\n * 为什么值得独立成文件：这三条路由回答同一个问题 —— **渲染页与壁纸载荷从哪个源、\n * 经哪条路径出去**（同源应用源 / 我们自监听的第二个 loopback 端口）。\n * \"哪条路径服务什么、围栏在哪\"都在一处，\n * 而**依赖写在签名上**（`c`）。\n *\n * 契约：`registerSceneServeRoutes(webServer, c)`；`c` 里是这一族**用到但不属于它**的东西：\n *   · `disposers` / `base`            ← 清理句柄数组与路径前缀\n *   · `WEBWALLGL_DIR`                  ← 渲染页根目录（`/scene-live` 的目录围栏基准）\n *   · `WEBWALLGL_PKG_DIR`              ← npm 依赖 `webwallgl` 的包目录（`/scene-live/engine/` 的围栏基准；未安装为 null）\n *   · `traceRequests`                  ← 逐请求记录（应用源；媒体源那条在 handleSceneFiles 内）\n *   · `serveFile`                      ← 静态发送器（Range / HEAD / 缓存头）\n *   · `appendDiagLine`                 ← 围栏拒绝的落盘留痕\n *   · `log`                            ← `lib/log.js` 的宿主日志入口（围栏拒绝按 `warn` 分级）\n *   · `handleSceneFiles`               ← `/scene-files` 的**共用处理函数**（两处挂载：应用源 + 媒体源）\n *   · `mediaOriginInfo`                ← 媒体源地址与端口的**访问器**\n *   · `payloadProgress`                ← 载荷传输账本快照（首帧看护分辨「在下载」与「出不了帧」）\n * 媒体源服务本身（`handleSceneFiles` / `ensureMediaOrigin` / `mediaOrigin*`）住在\n * `lib/media-origin.js`（`handleSceneFiles` 的本体在 `lib/serve.js`）：`/inventory` 也消费\n * `mediaOriginBase()`（给网页壁纸拼 media/preview 前缀），而 `mediaOrigin` 是该模块的**可变量**\n * ⇒ 只能以函数/访问器形式出去，传值就是陈旧快照。\n *\n * 不变量：\n *   · **两处挂载共用同一段处理逻辑**（`handleSceneFiles(req, res, mount)`）：应用源与媒体源的行为\n *     必须一致（目录围栏 / CORS / shim+seed 注入 / Range）；`mount` **只**影响请求记录 ——\n *     应用源逐请求全记（量小），媒体源只记文档型请求与错误（网页壁纸子资源太多，全量会冲掉诊断环）。\n *   · **目录围栏**：`/scene-live` 只在 `WEBWALLGL_DIR`（`engine/` 下则在 `WEBWALLGL_PKG_DIR`）内、\n *     `/scene-files` 只在壁纸目录内解析目标；\n *     越界一律 403 **且带自解释文案 + appendDiagLine 留痕**（用户截图即可定位，不必先看日志）。\n *   · **缓存头分型**：`/scene-live` 的两份 HTML 必须 no-store，其余（渲染页脚本、引擎）走\n *     可重验证缓存 —— 引擎文件名不带哈希，升级 `webwallgl` 后同名换内容；`/scene-files` 的 HTML 同样 no-store（带注入的\n *     shim/种子），其余文件走**可重验证缓存**（ETag + Last-Modified → 304）：`scene.pkg`\n *     100–336MB，内容由 size+mtime 唯一确定，让浏览器复用手上的字节是本族最贵那条路径的解药。\n *   · **`/scene-live/index.html` 注入遮挡桥**（沿 `/scene-files` 的 shim 注入先例）：读盘 →\n *     `<head>` 后插 `<script src=…/occlusion-bridge.js?v=<插件版本>>` → 自设 text/html 出站；\n *     只 GET 注入（HEAD 走 serveFile 原样），读盘失败落回 serveFile 常规路径。桥把父页\n *     postMessage 转成 `window.__weSetOcclusion`（`lib/webwallgl/renderer.js` 曝光），职责见\n *     `lib/webwallgl/occlusion-bridge.js` 文件头。\n *   · `OPTIONS` 由 `handleSceneFiles` 直接放行（媒体源上的跨源 fetch + Range 预检）。\n *   · 注册返回值必须推进 `c.disposers`，否则卸载 / HMR 后路由仍挂着已释放的处理器。\n */\n\nimport { readFileSync } from 'node:fs';\nimport { createHash } from 'node:crypto';\nimport { dirname, join, resolve, sep } from 'node:path';\nimport { fileURLToPath } from 'node:url';\n\n/**\n * 桥 script 的缓存破坏参数：**桥文件内容的 sha256 前 12 位**（不是插件版本）——\n * 任何一次桥改动都换 URL，不必等可重验证缓存的往返。读不到文件回落 '0'\n *（no-store 的 index.html 本就带着新引用）。\n */\nlet occlusionBridgeVersionCache;\nfunction occlusionBridgeVersion() {\n  if (occlusionBridgeVersionCache !== undefined) return occlusionBridgeVersionCache;\n  try {\n    const bridgePath = resolve(dirname(fileURLToPath(import.meta.url)), '../webwallgl/occlusion-bridge.js');\n    occlusionBridgeVersionCache = createHash('sha256').update(readFileSync(bridgePath)).digest('hex').slice(0, 12);\n  } catch {\n    occlusionBridgeVersionCache = '0';\n  }\n  return occlusionBridgeVersionCache;\n}\n\n/** `/scene-live/engine/<file>` → `<WEBWALLGL_PKG_DIR>/<file>` (lib/webwallgl/renderer.js imports from here). */\nconst ENGINE_PREFIX = 'engine/';\n\n/** 注入契约（P2-7A / ADR-0013 D12）：本族从 `c` 消费的**必需**键 —— 门面/组件行调用点必须逐键给到（判据 test/verify-inject-contracts.mjs 双向对账）。 */\nexport const DEPS = ['disposers', 'base', 'WEBWALLGL_DIR', 'WEBWALLGL_PKG_DIR', 'appendDiagLine', 'traceRequests', 'serveFile', 'handleSceneFiles', 'mediaOriginInfo', 'payloadProgress', 'log'];\n\nexport function registerSceneServeRoutes(webServer, c) {\n  const {\n    disposers, base: BASE, WEBWALLGL_DIR, WEBWALLGL_PKG_DIR, appendDiagLine, traceRequests, serveFile,\n    handleSceneFiles, mediaOriginInfo, payloadProgress, log,\n  } = c;\n\n  // 3c-2. WebWallGL live renderer page: our adapter page from lib/webwallgl/,\n  //       plus the engine itself from the `webwallgl` npm dependency under\n  //       `engine/`. Same-origin and NOT sandboxed: the parent page drives it\n  //       through frame.contentWindow.__wp / __wpStats, and backdrop-filter\n  //       (liquid glass) can sample the composited output. Scene scripts stay\n  //       confined inside WebWallGL's own SceneScript sandbox.\n  disposers.push(webServer.register({\n    kind: 'prefix',\n    path: `${BASE}/scene-live`,\n    handler: (req, res) => {\n      traceRequests(res, 'scene-live', new URL(req.url || '/', 'http://x').pathname);\n      const method = (req.method || 'GET').toUpperCase();\n      if (method !== 'GET' && method !== 'HEAD') { res.statusCode = 405; res.end('method not allowed'); return; }\n      let rest;\n      try {\n        rest = decodeURIComponent(new URL(req.url || '/', 'http://x').pathname.slice(`${BASE}/scene-live`.length));\n      } catch {\n        res.statusCode = 400; res.end('bad request'); return;\n      }\n      rest = rest.replace(/^\\/+/, '');\n      if (!rest || rest.endsWith('/')) rest += 'index.html';\n      const isEngine = rest.startsWith(ENGINE_PREFIX);\n      if (isEngine && !WEBWALLGL_PKG_DIR) {\n        log.warn('scene-live engine missing: npm dependency `webwallgl` is not installed');\n        res.setHeader('Cache-Control', 'no-store');\n        res.statusCode = 404; res.end('webwallgl-not-installed'); return;\n      }\n      const rootDir = isEngine ? WEBWALLGL_PKG_DIR : WEBWALLGL_DIR;\n      const abs = resolve(rootDir, isEngine ? rest.slice(ENGINE_PREFIX.length) : rest);\n      // Directory fence: nothing outside the page tree / the engine package is ever served.\n      if (abs === rootDir || !abs.startsWith(rootDir + sep)) {\n        // 自解释的 403：谁被拦、从哪来。这行文字会直接显示在壁纸层上 —— 用户\n        // 截图即可定位。\n        appendDiagLine('fence', { route: 'scene-live', rest: rest.slice(0, 160), referer: String(req.headers.referer || '').slice(0, 120), dest: req.headers['sec-fetch-dest'] || '' });\n        // 围栏拒绝 = 有请求被挡下 ⇒ 影响显示效果的非正常表现 ⇒ warn。\n        log.warn(`scene-live fenced: rest=\"${rest}\" referer=\"${req.headers.referer || '-'}\" ua-iframe=${req.headers['sec-fetch-dest'] || '-'}`);\n        res.setHeader('Cache-Control', 'no-store');\n        res.statusCode = 403; res.end(`forbidden-scene-live[${rest}]`); return;\n      }\n      // No file here carries a content hash in its name (the engine keeps its\n      // name across `webwallgl` upgrades): the two HTML documents are no-store,\n      // everything else revalidates (ETag / 304).\n      if (rest === 'index.html' || rest === 'default-wallpaper/index.html') {\n        res.setHeader('Cache-Control', 'no-store');\n        // 3c-2b. 遮挡桥注入（沿 handleSceneFiles 的 shim 注入先例：读盘 → <head> 后插标签\n        //        → 自设 text/html 出站）：index.html 是渲染页入口，遮挡消息桥必须随文档到达\n        //        （父页 postMessage → 页内桥 → window.__weSetOcclusion → 遮挡管线）。只注\n        //        index.html（目录形态已归一成它）；default-wallpaper 是无渲染器的静态兜底页，\n        //        不需要桥。index.html 本就 no-store（注入体必须随文档新鲜）。\n        if (method === 'GET' && rest === 'index.html') {\n          let html;\n          try { html = readFileSync(join(WEBWALLGL_DIR, 'index.html'), 'utf8'); } catch { html = ''; }\n          if (html) {\n            // `?v=<桥内容哈希>` 做缓存破坏：任何一次桥改动都换 URL，不依赖重验证往返。\n            const tag = `<script src=\"${BASE}/scene-live/occlusion-bridge.js?v=${occlusionBridgeVersion()}\"></script>`;\n            const m = /<head[^>]*>/i.exec(html);\n            html = m\n              ? html.slice(0, m.index + m[0].length) + tag + html.slice(m.index + m[0].length)\n              : tag + html;\n            res.setHeader('Content-Type', 'text/html; charset=utf-8');\n            res.end(html);\n            return;\n          }\n          // 源文件读不到（异常态）⇒ 落回 serveFile 的常规 404 路径，不自造响应。\n        }\n        serveFile(abs, req, res, method === 'HEAD');\n        return;\n      }\n      serveFile(abs, req, res, method === 'HEAD', { revalidate: true });\n    },\n  }));\n\n  // 3c-3. 应用源挂载：渲染页（同源非沙箱 frame）取 scene.pkg / project.json。\n  disposers.push(webServer.register({\n    kind: 'prefix',\n    path: `${BASE}/scene-files`,\n    handler: (req, res) => handleSceneFiles(req, res, 'app'),\n  }));\n\n  // 3c-3b. 诊断：上报媒体源地址（verify 脚本与用户截图都能一眼看出网页壁纸\n  //        到底从哪个源加载）。端口来自 `lib/media-origin.js` 的可变量 ⇒ 只经访问器取。\n  disposers.push(webServer.register({\n    kind: 'prefix',\n    path: `${BASE}/media-origin`,\n    handler: (req, res) => {\n      mediaOriginInfo().then((info) => {\n        res.setHeader('Content-Type', 'application/json; charset=utf-8');\n        res.setHeader('Cache-Control', 'no-store');\n        res.end(JSON.stringify(info));\n      });\n    },\n  }));\n\n  // 3c-3c. 载荷进度（客户端首帧看护用）：`?token=<sceneLiveSrc>` →\n  //        `{ ok, served, size, active, transfers, completed, startedAt, lastByteAt, lastEndAt }`。\n  //\n  // 为什么需要这条：首帧**必须等整包到齐**（渲染页 2.0.2 在 `pkg body` 之前不发任何东西），\n  // 而已知最坏形态是\"传输被别的实例饿死\"（同一份 336MB 包：媒体源上 0.6s，应用源上\n  // 出现过 15–74s 甚至永不返回）—— 客户端只有墙钟，分辨不出\"在下载\"与\"渲染不出来\"，\n  // 于是把前者写进共享失败记忆。服务端是唯一知道字节在不在动的地方。\n  // `ok:false` = 这个 token 一次传输都没见过 = **未知**（客户端据此回落墙钟预算）。\n  disposers.push(webServer.register({\n    kind: 'prefix',\n    path: `${BASE}/scene-payload-progress`,\n    handler: (req, res) => {\n      let token;\n      try { token = new URL(req.url || '/', 'http://x').searchParams.get('token') || ''; } catch { token = ''; }\n      res.setHeader('Content-Type', 'application/json; charset=utf-8');\n      res.setHeader('Cache-Control', 'no-store');\n      res.end(JSON.stringify(payloadProgress(token)));\n    },\n  }));\n}\n"
    },
    {
      "path": "lib/routes/upload.js",
      "content": "/**\n * routes/upload.js — **上传资产族**路由：导入（`/upload`）、删除（`/remove`）与\n * 上传目录切换（`/upload-dir`）。\n *\n * 为什么值得独立成文件：这三条路由是**唯一**会写上传目录的一组 ——\n * \"谁能动上传目录、动完谁负责迁移\"收在本文件里就能一次读完。\n * 这三条注册与它们的依赖都在一处，\n * 而**依赖写在签名上**（`c`）。\n *\n * 契约：`registerUploadRoutes(webServer, c)`；`c` 里是这一族**用到但不属于它**的东西。\n * 上传资产的**存储层**（`ensureUploadDir` / `readUploadMeta` / `metaEntry` / `setUploadMeta` /\n * `removeUploadMeta` / `resolveUploadFile` / `setUploadDir` / `UPLOAD_MAX_BYTES`）住在\n * `lib/upload-store.js`（`normalizeUserDir` 也由它导出）；MIME→扩展名契约表 `UPLOAD_EXT` 随\n * 「目录与路径」族住在 `lib/media/media-dirs.js`。两者都由门面注入，不是路由族的私产：存储层由\n * `/inventory` 与上传族共用（`/we-assets-dir` 只用到 `normalizeUserDir`），`UPLOAD_EXT` 是\n * `test/verify-contracts.mjs` 读取的**跨半边契约表**。它们的归属是那条依赖，不是路由族的边界。\n *   · `disposers` / `base`        ← 清理句柄数组与路径前缀\n *   · `tokenFor`                  ← `apply` 作用域的 token 生成器（多族共用）\n *   · `UPLOAD_EXT` / `UPLOAD_MAX_BYTES` ← MIME→扩展名映射与 512MB 上限\n *   · `CONTROL_JSON_MAX_BYTES`    ← 小控制面 JSON 请求体的统一上限（64KB，见下\"收 body\"）\n *   · `ensureUploadDir` / `readUploadMeta` / `metaEntry` / `setUploadMeta` / `removeUploadMeta`\n *   · `resolveUploadFile` / `setUploadDir` / `normalizeUserDir`\n *   · `armBodyIdleTimeout` / `lingerClose` ← 请求体 idle 超时与\"写应答后再断\"的收尾\n *\n * 不变量：\n *   · **收 body 必须同时满足两条**（本族是本仓该不变量的权威表述处）：\n *     ① **有上限** —— 逐块累加却从不比较长度，异常大的请求体会把宿主堆无界撑大（默认只听\n *        loopback，但 webserver 允许 `host: 0.0.0.0`，而这几条都是 POST）。上限用\n *        `CONTROL_JSON_MAX_BYTES`（小控制面 JSON），大载荷走流式落盘那条腿（见下）。\n *     ② **收完一次性解码** —— 逐块 `body += chunk` 会把落在两个 TCP 分片之间的多字节码点\n *        切成 U+FFFD，用户可见字符串（壁纸 id / 字体名 / 字体族）被静默写坏且客户端不知道。\n *        正确形态是 `chunks.push(chunk)` + `Buffer.concat(chunks).toString('utf8')`。\n *     判据：`test/verify-body-caps.mjs` 从磁盘枚举**每一个** `req.on('data')` 站点并断言上限在位 ——\n *     这条从\"靠人记得抄\"改成机器判。\n *   · **上传目录是跨族共享的可变量**：本模块一律经上面那些模块级助手读写它，**不得**缓存目录值的\n *     副本 —— `setUploadDir` 会重新赋值它，缓存副本会让\"改了目录却仍写回老目录\"静默发生。\n *   · **流式落盘**：边收边写 `.tmp`、边更新 sha256，完成后 rename 发布。**不得**把上限 512MB 的\n *     请求体整个缓冲在内存里；`.tmp` 与目标同目录，rename 才是同设备原子操作。\n *   · **中途断开必须清理**：上传中途关标签页 / 断网不会走 `req 'end'` / `'error'` / 超时\n *     ⇒ `req 'close'` 里必须销毁写流并清 `.tmp`，否则上传目录里留下一个打开的文件描述符与\n *     最多 512MB 的 `.tmp`（启动清扫只看 transcode / ffmpeg / preview 目录，不扫 uploads）。\n *     而 `completed` 置位后**不得**再销毁写流 —— 否则发布回调不执行，文件永远停在 `.tmp`。\n *   · **内容去重**：同 sha256 的重复上传返回既有条目（`duplicate: true`）并丢弃刚收的临时文件；\n *     meta 的 sha256 **无条件写**（没有 title 也要写），否则去重比对不到哈希、形同虚设。\n *   · **背压**：`ws.write` 返回 false ⇒ `req.pause()`，`'drain'` 后恢复。\n *   · `armBodyIdleTimeout` 60s 无数据 ⇒ 408（客户端连上不发数据不得永久占住 socket）。\n *   · `/remove` 只删 uploads 目录内、`up-…` 形状的 id：`resolveUploadFile` 复检规范化后的前缀\n *     ⇒ 路径穿越不可能（id 由宿主生成，不接受调用方给的路径）。\n *   · `/upload-dir` 只接受**绝对路径**（`normalizeUserDir`），且该路径必须能解析成目录\n *     （缺失则 mkdir；存在但不是目录 ⇒ 400），否则拒绝而不是留下一个坏配置。\n *   · 注册返回值必须推进 `c.disposers`，否则卸载 / HMR 后路由仍挂着已释放的处理器。\n */\n\nimport { createHash } from 'node:crypto';\nimport { createWriteStream, existsSync, mkdirSync, renameSync, statSync, unlinkSync } from 'node:fs';\nimport { join } from 'node:path';\n// 收 body 的**唯一缓冲实现**（累加 + 字节计闸 + 一次解码）；流式落盘那两处是本模块的\n// 结构性豁免，见 `lib/http-body.js` 文件头与下面的\"流式落盘\"不变量。\nimport { bodyReader } from '../http-body.js';\n\n/** 注入契约（P2-7A / ADR-0013 D12）：本族从 `c` 消费的**必需**键 —— 门面/组件行调用点必须逐键给到（判据 test/verify-inject-contracts.mjs 双向对账）。 */\nexport const DEPS = ['disposers', 'base', 'tokenFor', 'UPLOAD_EXT', 'UPLOAD_MAX_BYTES', 'CONTROL_JSON_MAX_BYTES', 'ensureUploadDir', 'readUploadMeta', 'metaEntry', 'setUploadMeta', 'removeUploadMeta', 'resolveUploadFile', 'setUploadDir', 'normalizeUserDir', 'armBodyIdleTimeout', 'lingerClose'];\n\nexport function registerUploadRoutes(webServer, c) {\n  const {\n    disposers, base: BASE, tokenFor, UPLOAD_EXT, UPLOAD_MAX_BYTES, CONTROL_JSON_MAX_BYTES,\n    ensureUploadDir, readUploadMeta, metaEntry, setUploadMeta, removeUploadMeta,\n    resolveUploadFile, setUploadDir, normalizeUserDir, armBodyIdleTimeout, lingerClose,\n  } = c;\n  // 4. Custom upload (raw body; MIME whitelist; writes into the uploads dir).\n  //    Returns the new wallpaper entry so the client can refresh the inventory.\n  disposers.push(webServer.register({\n    kind: 'exact',\n    path: `${BASE}/upload`,\n    handler: (req, res) => {\n      const method = (req.method || 'GET').toUpperCase();\n      if (method !== 'POST') {\n        res.statusCode = 405; res.end('method not allowed'); return;\n      }\n      const query = new URL(req.url || '/', 'http://x').searchParams;\n      const title = (query.get('title') || '').trim().slice(0, 80);\n      const ctype = String(req.headers['content-type'] || '').split(';')[0].trim().toLowerCase();\n      const ext = UPLOAD_EXT[ctype];\n      if (!ext) {\n        res.statusCode = 415;\n        res.setHeader('Content-Type', 'application/json; charset=utf-8');\n        res.end(JSON.stringify({\n          error: '不支持的格式：' + ctype + '（仅支持 JPG / PNG / MP4）',\n        }));\n        return;\n      }\n      // 流式落盘：边收边写 .tmp 文件、边更新 sha256，完成后 rename 发布 —\n      // 不把最多 512MB 的文件整个缓冲在内存里。.tmp 在同目录，rename 为\n      // 同设备原子操作；失败路径（超限/超时/写错误）由 ws 'close' 清理临时文件。\n      const dir = ensureUploadDir();\n      const id = 'up-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8);\n      const fileAbs = join(dir, id + '.' + ext);\n      const tmpAbs = fileAbs + '.tmp';\n      const hash = createHash('sha256');\n      const ws = createWriteStream(tmpAbs);\n      let size = 0;\n      let failed = false;\n      let completed = false; // 请求已成功应答 (临时文件已 rename 或本就该保留)\n      let tmpCleaned = false; // 防重复清理\n      const cleanupTmp = () => {\n        if (tmpCleaned) return;\n        tmpCleaned = true;\n        try { unlinkSync(tmpAbs); } catch { /* ignore */ }\n      };\n      const fail = (code, payload) => {\n        if (failed) return;\n        failed = true;\n        try { ws.destroy(); } catch { /* ignore */ } // 'close' 里 cleanupTmp\n        res.statusCode = code;\n        res.setHeader('Content-Type', 'application/json; charset=utf-8');\n        res.end(JSON.stringify(payload));\n        lingerClose(req, res);\n      };\n      ws.on('error', () => fail(500, { error: 'upload write failed' }));\n      ws.on('close', () => { if (failed) cleanupTmp(); });\n      // 上传中途关标签页/断网：不会走 req 'end' / 'error' / 超时 ⇒ 必须在这里销毁写流\n      // 并清 .tmp。否则上传目录里留下一个打开的文件描述符 + 最多 512MB 的 .tmp\n      //（启动清扫只看 transcode/ffmpeg/preview 目录，不扫 uploads）。\n      req.once('close', () => {\n        if (completed || failed) return;\n        failed = true;\n        try { ws.destroy(); } catch { /* ignore */ } // 'close' 里 cleanupTmp\n        cleanupTmp();\n      });\n      // 60s 无数据即超时（见 armBodyIdleTimeout）。\n      armBodyIdleTimeout(req, () => fail(408, { error: 'request timeout' }));\n      req.on('data', (c) => {\n        if (failed) return;\n        size += c.length;\n        if (size > UPLOAD_MAX_BYTES) {\n          fail(413, { error: '文件过大（上限 512MB）' });\n          return;\n        }\n        hash.update(c);\n        // 背压：写流缓冲满时暂停读取，drain 后恢复。\n        if (!ws.write(c)) req.pause();\n      });\n      ws.on('drain', () => { if (!failed) req.resume(); });\n      req.on('end', () => {\n        if (failed) return;\n        // 请求体已完整收到: 从此处起临时文件由下面的 ws.end 回调负责发布\n        // (rename 或清理), req 'close' 不得再销毁写流 (否则回调不会执行)。\n        completed = true;\n        ws.end(async () => {\n          try {\n            const sha = hash.digest('hex');\n            // Content dedup: uploading the SAME file again must not create a\n            // duplicate entry — return the existing wallpaper instead. meta\n            // stores each upload's sha256; legacy entries without a hash never\n            // match, so pre-existing uploads are unaffected.\n            const meta = readUploadMeta();\n            let dupId = null;\n            for (const metaId of Object.keys(meta)) {\n              if (metaEntry(meta, metaId).sha256 === sha) { dupId = metaId; break; }\n            }\n            if (dupId) {\n              const existing = resolveUploadFile(dir, dupId);\n              if (existing && existsSync(existing)) {\n                // 内容已存在：丢弃刚收的临时文件，返回既有条目。\n                failed = true; // 让 ws 'close' 清掉临时文件\n                const eext = existing.slice(existing.lastIndexOf('.') + 1).toLowerCase();\n                const etype = eext === 'mp4' ? 'video' : 'image';\n                const etitle = metaEntry(meta, dupId).title || dupId;\n                res.setHeader('Content-Type', 'application/json; charset=utf-8');\n                res.end(JSON.stringify({\n                  id: dupId,\n                  title: etitle,\n                  type: etype,\n                  playable: true,\n                  duplicate: true,\n                  media: `${BASE}/media/${tokenFor(existing)}`,\n                  preview: etype === 'image' ? `${BASE}/preview/${tokenFor(existing)}` : null,\n                }));\n                return;\n              }\n              // meta says the id exists but the file is gone — fall through and\n              // store a fresh copy under a new id.\n            }\n            renameSync(tmpAbs, fileAbs);\n            // meta 无条件写（即便无 title 也记 sha256）：否则重复上传同一文件\n            // 时 dedup 比对不到哈希，内容去重形同虚设。\n            // 写已串行化（enqueueConfigWrite）⇒ **等它落盘再应答**：保持\"响应即已持久化\"，\n            // 且下一次上传的 dedup 一定读得到这次的 sha256。\n            await setUploadMeta(id, title || id, sha);\n            const type = ext === 'mp4' ? 'video' : 'image';\n            const payload = {\n              id,\n              title: title || id,\n              type,\n              playable: true,\n              media: `${BASE}/media/${tokenFor(fileAbs)}`,\n              preview: type === 'image' ? `${BASE}/preview/${tokenFor(fileAbs)}` : null,\n            };\n            res.setHeader('Content-Type', 'application/json; charset=utf-8');\n            res.end(JSON.stringify(payload));\n          } catch (err) {\n            failed = true; // 让 ws 'close' 清掉临时文件\n            res.statusCode = 500;\n            res.setHeader('Content-Type', 'application/json; charset=utf-8');\n            res.end(JSON.stringify({ error: String(err && err.message ? err.message : err) }));\n          }\n        });\n      });\n      req.on('error', () => {\n        if (!failed) {\n          failed = true;\n          try { ws.destroy(); } catch { /* ignore */ } // 'close' 里 cleanupTmp\n          res.statusCode = 400; res.end('request error');\n        }\n      });\n    },\n  }));\n\n  // 5. Custom upload removal — ONLY files inside the uploads dir with an\n  //    `up-…` id (path traversal is impossible: the id is host-generated and\n  //    resolveUploadFile re-checks the normalized prefix).\n  disposers.push(webServer.register({\n    kind: 'exact',\n    path: `${BASE}/remove`,\n    handler: (req, res) => {\n      const method = (req.method || 'GET').toUpperCase();\n      if (method !== 'POST') {\n        res.statusCode = 405; res.end('method not allowed'); return;\n      }\n      // 60s 无数据即超时（见 armBodyIdleTimeout）。\n      let timedOut = false;\n      let tooLarge = false;\n      armBodyIdleTimeout(req, () => {\n        timedOut = true;\n        res.statusCode = 408;\n        res.setHeader('Content-Type', 'application/json; charset=utf-8');\n        res.end(JSON.stringify({ error: 'request timeout' }));\n      });\n      // 上限 + 收完一次性解码 —— 这两件事的唯一实现在 `lib/http-body.js`。\n      const reader = bodyReader(req, {\n        maxBytes: CONTROL_JSON_MAX_BYTES,\n        shouldStop: () => timedOut,\n        onOverflow: () => {\n          tooLarge = true;\n          res.statusCode = 413;\n          res.setHeader('Content-Type', 'application/json; charset=utf-8');\n          res.end(JSON.stringify({ error: 'payload too large' }));\n        },\n      });\n      req.on('data', reader.onData);\n      req.on('end', async () => {\n        if (timedOut || tooLarge) return;\n        const body = reader.text();\n        let id = null;\n        try { id = JSON.parse(body || '{}').id; } catch { /* ignore */ }\n        const dir = ensureUploadDir();\n        const abs = resolveUploadFile(dir, id);\n        if (!abs) {\n          res.statusCode = 400;\n          res.setHeader('Content-Type', 'application/json; charset=utf-8');\n          res.end(JSON.stringify({ error: 'invalid upload id' }));\n          return;\n        }\n        let removed = false;\n        try { unlinkSync(abs); removed = true; } catch { /* ignore */ }\n        // meta 写已串行化（enqueueConfigWrite）⇒ 等它落盘再应答（\"响应即已持久化\"）。\n        await removeUploadMeta(id);\n        res.setHeader('Content-Type', 'application/json; charset=utf-8');\n        res.end(JSON.stringify({ removed }));\n      });\n      req.on('error', () => { res.statusCode = 400; res.end('request error'); });\n    },\n  }));\n\n  // 6. Change the upload directory (persisted to config.json; survives\n  //    restarts without env setup). Existing uploads migrate to the new\n  //    location by default. The user enters an absolute path in the settings\n  //    UI — most users prefer their data off the system (C:) drive.\n  disposers.push(webServer.register({\n    kind: 'exact',\n    path: `${BASE}/upload-dir`,\n    handler: (req, res) => {\n      const method = (req.method || 'GET').toUpperCase();\n      if (method !== 'POST') {\n        res.statusCode = 405; res.end('method not allowed'); return;\n      }\n      // 与同族其它两条同口径：idle 超时 + 上限 + 收完一次性解码（见文件头不变量）。\n      let timedOut = false;\n      let tooLarge = false;\n      armBodyIdleTimeout(req, () => {\n        timedOut = true;\n        res.statusCode = 408;\n        res.setHeader('Content-Type', 'application/json; charset=utf-8');\n        res.end(JSON.stringify({ error: 'request timeout' }));\n      });\n      // 上限 + 收完一次性解码 —— 唯一实现见 `lib/http-body.js`。\n      const reader = bodyReader(req, {\n        maxBytes: CONTROL_JSON_MAX_BYTES,\n        shouldStop: () => timedOut,\n        onOverflow: () => {\n          tooLarge = true;\n          res.statusCode = 413;\n          res.setHeader('Content-Type', 'application/json; charset=utf-8');\n          res.end(JSON.stringify({ error: 'payload too large' }));\n        },\n      });\n      req.on('data', reader.onData);\n      req.on('end', () => {\n        if (timedOut || tooLarge) return;\n        const body = reader.text();\n        let dirRaw = null;\n        let migrate = true;\n        try {\n          const o = JSON.parse(body || '{}');\n          dirRaw = o.dir;\n          migrate = o.migrate !== false;\n        } catch { /* ignore */ }\n        const dir = normalizeUserDir(dirRaw);\n        if (!dir) {\n          res.statusCode = 400;\n          res.setHeader('Content-Type', 'application/json; charset=utf-8');\n          res.end(JSON.stringify({\n            error: '请输入有效的绝对路径（如 D:\\\\MyWallpapers 或 /data/wallpapers）',\n          }));\n          return;\n        }\n        // The path must resolve to a directory (mkdir when missing; reject a\n        // path that exists as a FILE).\n        try { mkdirSync(dir, { recursive: true }); } catch { /* ignore */ }\n        let isDir = false;\n        try { isDir = statSync(dir).isDirectory(); } catch { /* ignore */ }\n        if (!isDir) {\n          res.statusCode = 400;\n          res.setHeader('Content-Type', 'application/json; charset=utf-8');\n          res.end(JSON.stringify({ error: '无法在该路径创建目录（权限不足或路径被占用）' }));\n          return;\n        }\n        // setUploadDir 是异步的（迁移走线程池 + 写串行化）。\n        setUploadDir(dir, migrate).then(\n          (result) => {\n            res.setHeader('Content-Type', 'application/json; charset=utf-8');\n            res.end(JSON.stringify(result));\n          },\n          (err) => {\n            res.statusCode = 500;\n            res.setHeader('Content-Type', 'application/json; charset=utf-8');\n            res.end(JSON.stringify({ error: String(err && err.message ? err.message : err) }));\n          },\n        );\n      });\n      req.on('error', () => { res.statusCode = 400; res.end('request error'); });\n    },\n  }));\n}\n"
    },
    {
      "path": "lib/fs-paths.js",
      "content": "/**\n * fs-paths.js —— 用户目录归一 + 跨卷安全移动（两个**叶子级**工具）。\n *\n * 为什么单独成模块（而不是留在门面或 upload-store 里）：\n *   · 它们是**纯函数 + node 内置**，没有门面状态依赖，任何一层都可以直接用；\n *   · 上游把它们留在 `lib/index.js` 的**模块私有**位置（只被门面内的上传目录迁移用），\n *     而本分支的内核层（`lib/kernel/host-kernel.js`）与路由族也要用同一份语义 ——\n *     若从门面 import 就会形成 `内核 → 门面` 的环（本仓明令禁止）。\n *   · 因此这里保留**与上游逐字相同的实现**，作为唯一真源；门面与内核都从这里取。\n *\n * `moveFileP` 的跨卷回落不是可选优化：Windows 上把上传目录从 C: 挪到 D: 时\n * `rename` 必然 EXDEV —— 这就是用户实际会踩的那条路径。\n */\nimport { homedir } from 'node:os';\nimport { join, normalize } from 'node:path';\nimport { copyFile, rename, unlink } from 'node:fs/promises';\n\n// ⚠️ **不要**对 `node:fs/promises` 的函数再 `promisify`：那是回调式 API 的包装器，它会调\n// `rename(src, dst, cb)`，而 promises 版**忽略第三个参数**、返回自己的 promise ⇒ 回调永不触发\n// ⇒ 包装出的 promise **永不 settle** ⇒ 迁移整条链挂死（实测：改缓存/上传目录时插件不回包）。\n// 这正是本轮 `verify-cache-dir` 抓到的用户可见 bug；这里直接用 promises 版即可。\nconst renameP = rename;\nconst copyFileP = copyFile;\nconst unlinkP = unlink;\n\n/**\n * 路径的扩展名（小写、不含点）。门面与内核共用同一份 —— 上游把它做成扫描族工厂的闭包导出\n * （`createWallpaperScanKit` 的返回键），本分支抽到叶子模块，避免 `内核 → 门面` 的环。\n * @param {string} p\n * @returns {string}\n */\nexport function extOf(p) {\n  const s = String(p || '');\n  const dot = s.lastIndexOf('.');\n  const sepAt = Math.max(s.lastIndexOf('/'), s.lastIndexOf('\\\\'));\n  return dot > sepAt + 1 ? s.slice(dot + 1).toLowerCase() : '';\n}\n\n/**\n * 校验并归一用户给出的上传目录字符串：接受绝对路径（Windows 盘符 / UNC / POSIX）、\n * 可用 `~` 表示主目录；剥掉首尾引号；非法返回 `null`。\n * @param {unknown} raw\n * @returns {string|null}\n */\nexport function normalizeUserDir(raw) {\n  if (typeof raw !== 'string') return null;\n  let dir = raw.trim().replace(/^[\"']|[\"']$/g, '');\n  if (!dir) return null;\n  if (dir === '~' || dir.startsWith('~\\\\') || dir.startsWith('~/')) {\n    dir = join(homedir(), dir.slice(1));\n  }\n  if (/[\\u0000-\\u001f]/.test(dir)) return null;   // 控制字符 / NUL\n  const isAbsolute = /^[a-zA-Z]:[\\\\/]/.test(dir) || /^\\\\\\\\/.test(dir) || /^\\//.test(dir);\n  if (!isAbsolute) return null;\n  return normalize(dir);\n}\n\n/**\n * 移动文件；跨卷时回落到「复制 + 删除」（Windows 上 C: → D: 就是用户实际会踩的那条）。\n * @param {string} src\n * @param {string} dst\n * @returns {Promise<boolean>} 成功 true / 失败 false（不抛）\n */\nexport async function moveFileP(src, dst) {\n  try { await renameP(src, dst); return true; } catch { /* 跨卷 */ }\n  try {\n    await copyFileP(src, dst);\n    await unlinkP(src);\n    return true;\n  } catch { return false; }\n}\n"
    },
    {
      "path": "src/video-layer.js",
      "content": "/*\n * video-layer.js — **视频壁纸通道**：视频档的\"有画面了吗\" + 它的切换放行策略。\n *\n * 为什么单开一条通道：为**实时渲染**设计的那条路（`live-layer.js` 里的切层内容闸门、垫底图、\n * 心跳、载荷、GPU 抓帧…）对视频**只有一部分有意义**。\n * 实测后果：闸门的视频判据是\"手上已有一帧\"（`readyState ≥ 2`），而视频档**故意不设 poster**\n *（WE 的动图预览当 poster 会先播预览）⇒ 整次切换（含过场）被推迟到首个可解码帧：\n * 源越大越久、帧率上限越高越久，从秒级退化到十几秒。\n *\n * 判据（本文件的两条不变量）：\n *   ① **放行 ⇔ 屏上真的有画面**：海报图**已加载**（不是\"属性存在\"）｜首帧 `readyState ≥ 2`｜\n *      预算到期（兜底，避免拿不到海报就永远换不下去）。\n *   ② **没画面时旧壁纸留在屏上**：绝不露出这一层的底色。\n *      ⚠️ 不许改成\"poster 属性存在即放行\"：海报是按需抽帧生成的（与 4K 抽帧转码抢\n *      CPU，十几秒才到）⇒ 那十几秒屏上是一块**纯色**（层底色），观感比\"旧壁纸多留\n *      十几秒\"更糟。\n *\n * 本文件拥有：就绪判据（`videoContentReady` / `probeVideoPoster` / `VIDEO_POSTER_BUDGET_MS`）、\n * 媒体构建（`buildVideoMedia`：`<video>` / Edge 镜像画布 / poster / 音轨与 `playbackRate` / `object-fit`）、\n * 抽帧换源链路（源元数据探测 → 是否值得转码 → 进度轮询 → 换源或回退）。\n */\n\n/**\n * 海报预算：拿不到海报图时的兜底（到期放行 ⇒ 旧壁纸让位，最坏是黑一下再进正片）。\n *\n * ⚠️ 这个数是**用户感知的延迟上限**，实测调过两次：\n *   · 4000 ms — 诊断里出现 3907/3891/3887 ms 的整簇（全是预算触发的签名）：\n *     按需抽的海报图在 4K 源跑抽帧转码时会被抢 CPU，常常 4 秒内到不了 ⇒ 每次切换\n *     都等到预算；\n *   · 1200 ms — 海报要么很快到（已热时实测 213/215/218/231 ms），要么就让位给视频首帧。\n * 真正的根治不在这个常数上（见文件头\"抽帧换源\"段的待办：海报预抽/优先级）。\n */\nconst VIDEO_POSTER_BUDGET_MS = 1200;\n\n/**\n * 停滞上限：到这里仍然没有画面 ⇒ **停止等待，但也不放行空层**（不变量 ②：绝不露出这一层\n * 的底色）。旧壁纸继续留在屏上，只留一条 warn 日志。\n *\n * 为什么要这条：预算到期就放行不行 —— 视频档通常**没有 poster**（只认\n * `/video-preview/`）⇒ 放行那一刻屏上只有这一层的底色（=壁纸主色）。真机日志（桌面壳）\n * 抓到的正是这一幕：\n *   `gate-open … held=1201ms out=1 rs=0 ns=1 vw=0x0` → `loadedmetadata +2053ms` →\n *   `loadeddata +2095ms` → `presented +2167ms`\n * 也就是用户盯着那块纯色 1–2 秒（源慢时更久）。文件头那条实测结论早就写过：这种\"铺纯色\"\n * 的观感比\"旧壁纸多留一会儿\"更糟 —— 这里把它落到判据上。\n */\nconst VIDEO_STALL_GIVE_UP_MS = 15000;\n\n\n// ── 提交前预热：把\"取数\"挪出切换的关键路径 ────────────────────────────────────\n// 切换那一下真正要等的是**媒体元素的启动**：资源选择 → 取 moov → 解复用器初始化 →\n// 首帧解码。本机实测：宿主+磁盘 ~4ms、`loadedmetadata → presented` ~110ms，其余时间都是\n// \"还没开始取数\"。视频档**刻意不跑准备链**（`prepareVideoProbe` 会 `play()` ⇒ 第二个\n// 4K 解码器在跑，实测双解码卡顿），于是整段启动成本都压在关键路径上。\n//\n// 这里的折中：只预热到 **HAVE_METADATA**（`preload=\"metadata\"`、**绝不 play()**、muted）——\n// 解复用器与 moov 先就位，**一帧都不解码**；用户真的点了就把这个元素领养进层\n//（`consumeWarmVideo`），剩下的只是一帧的取数与解码。\n// 单槽位 + TTL：任何时刻最多一个预热元素，没人用就自己释放。\nconst VIDEO_WARM_TTL_MS = 20000;\n// 悬停预热的静默期：鼠标扫过一排卡片时不必把经过的每一张都摸一遍（见 warmVideoForPointer）。\nconst VIDEO_WARM_HOVER_MS = 120;\nlet videoWarm = null; // { url, el, timer }\nlet warmHoverTimer = 0; // 待发的悬停预热\nfunction disposeWarmVideo() {\n  const w = videoWarm;\n  videoWarm = null;\n  if (warmHoverTimer && typeof clearTimeout === \"function\") {\n    try { clearTimeout(warmHoverTimer); } catch { /* ignore */ }\n    warmHoverTimer = 0;\n  }\n  if (!w) return;\n  if (w.timer && typeof clearTimeout === \"function\") { try { clearTimeout(w.timer); } catch { /* ignore */ } }\n  try { w.el.removeAttribute(\"src\"); w.el.load(); } catch { /* ignore */ }\n}\n/**\n * 预热一个视频源（只到元数据）。\n *\n * ⚠️ 三条不变量：\n *   · **绝不 `play()`、绝不 `autoplay`** —— 预热不得引进第二个解码器（本文件头的取舍）；\n *   · 同一个 url 幂等（槽位里已经是它就直接返回）；\n *   · 单槽位：换一个候选就把上一个释放掉（点选来回扫不会攒下一串解复用器）。\n */\nfunction warmVideoUrl(url) {\n  const u = String(url || \"\");\n  if (!u || typeof document === \"undefined\" || typeof document.createElement !== \"function\") return;\n  if (videoWarm && videoWarm.url === u) return;\n  disposeWarmVideo();\n  let el;\n  try { el = document.createElement(\"video\"); } catch { return; }\n  if (!el || typeof el.load !== \"function\") return;\n  try {\n    el.preload = \"metadata\";      // ← 只取 moov：Chromium 拿到元数据就停\n    el.muted = true;\n    el.loop = true;\n    el.autoplay = false;          // ← 预热不解码帧\n    el.setAttribute(\"playsinline\", \"\");\n    el.src = u;              // 赋 src 本身就会启动资源选择；**不再调 load()** ——\n                             // 同值重启资源选择等于白跑一次取数（本文件建层那段有同类注释）。\n  } catch { return; }\n  const timer = typeof setTimeout === \"function\" ? setTimeout(() => {\n    if (videoWarm && videoWarm.el === el) disposeWarmVideo();\n  }, VIDEO_WARM_TTL_MS) : 0;\n  videoWarm = { url: u, el, timer };\n  liveLog(\"video-warm\", \"预热（仅元数据，不解码） \" + u.slice(Math.max(0, u.lastIndexOf(\"/\") + 1)).slice(-24));\n}\n/** 领养预热好的元素（同 url 才给）。命中即交出，槽位随之清空。 */\nfunction consumeWarmVideo(url) {\n  const w = videoWarm;\n  if (!w || w.url !== String(url || \"\")) return null;\n  videoWarm = null;\n  if (w.timer && typeof clearTimeout === \"function\") { try { clearTimeout(w.timer); } catch { /* ignore */ } }\n  liveLog(\"video-warm\", \"领养预热元素 \" + String(w.el.readyState === undefined ? \"-\" : w.el.readyState) + \" rs\");\n  return w.el;\n}\n/**\n * 指针落到某张壁纸卡上时预热它。\n *\n * 两个触发点，窗口不一样：\n *   · `pointerdown`（immediate=true）—— 点击发生在抬手，按下到抬手就是白捡的窗口；\n *   · `pointerover`（immediate=false）—— 鼠标**停在**卡片上通常几百毫秒到几秒，窗口更大；\n *     扫过一排卡片时靠 120ms 的抖动静默掉（单槽位 + 幂等已经把开销压到可忽略，但没必要\n *     扫一次就把一排源都摸一遍）。\n * 卡片靠 `data-we-id`（见 picker-modal / quick-panel）自报身份；解析不到就静默返回。\n */\nfunction warmVideoForPointer(ev, immediate) {\n  try {\n    const t = ev && ev.target;\n    const card = t && typeof t.closest === \"function\" ? t.closest(\"[data-we-id]\") : null;\n    const id = card && typeof card.getAttribute === \"function\" ? String(card.getAttribute(\"data-we-id\") || \"\") : \"\";\n    // 任何一次\"落到某张卡上\"都先撤掉待发的悬停预热：人已经离开了上一张。\n    if (warmHoverTimer && typeof clearTimeout === \"function\") {\n      try { clearTimeout(warmHoverTimer); } catch { /* ignore */ }\n    }\n    warmHoverTimer = 0;\n    if (!id) return;\n    const list = (selection.inventory && selection.inventory.wallpapers) || [];\n    const w = list.find((x) => x && String(x.id) === id);\n    if (!w || w.type !== \"video\" || !w.media) return;\n    if (immediate || typeof setTimeout !== \"function\") { warmVideoUrl(w.media); return; }\n    const url = w.media;\n    warmHoverTimer = setTimeout(() => { warmHoverTimer = 0; warmVideoUrl(url); }, VIDEO_WARM_HOVER_MS);\n  } catch { /* 预热是增强：任何异常都不许影响切换 */ }\n}\n\n/**\n * 探一次海报图（`<video poster>` 的 URL）。\n *\n * 为什么要探：`poster` **属性存在**不等于**图已加载** —— 属性刚设上时 `<video>` 还是透明的，\n * 那一瞬屏上就是层底色。只有 `onload` 才算\"有画面\"。\n * 返回一个取消函数；`Image` 不可用（精简 DOM / 挂载台）时**立即**回调 `onReady`（不拦）。\n */\nfunction probeVideoPoster(video, onReady, onFail) {\n  const url = video && video.getAttribute ? String(video.getAttribute(\"poster\") || \"\") : \"\";\n  if (video) { try { video.__wePosterReady = false; } catch { /* ignore */ } }\n  // 判不了就不拦：没有海报 URL、或环境没有 `Image`（精简 DOM / 挂载台）⇒ 直接当\"已就绪\"。\n  if (!url || typeof Image !== \"function\") {\n    if (video) { try { video.__wePosterReady = true; } catch { /* ignore */ } }\n    onReady();\n    return () => {};\n  }\n  let done = false;\n  const img = new Image();\n  img.onload = () => {\n    if (done) return;\n    done = true;\n    try { video.__wePosterReady = true; } catch { /* ignore */ }\n    onReady();\n  };\n  img.onerror = () => { if (!done) { done = true; onFail(); } };\n  try { img.src = url; } catch { if (!done) { done = true; onFail(); } }\n  return () => { done = true; };\n}\n\n/**\n * 视频层现在\"有画面\"吗（**通道自己的判据**，与实时那条路的闸门无关）。\n *\n * 顺序即优先级：作者静帧/海报（已加载）> 首帧 > 都没有。Edge 的镜像画布那条腿由调用方\n * 先判（画布底写死 #000，要等真画上一笔）。\n */\nfunction videoContentReady(video) {\n  if (!video) return true;\n  const hasPoster = !!(video.getAttribute && video.getAttribute(\"poster\"));\n  if (hasPoster && video.__wePosterReady === true) return true; // 海报真到了 ⇒ 屏上有图\n  if (Number(video.readyState) >= 2) return true;              // HAVE_CURRENT_DATA = 手上有帧\n  return false;                                                // 都没有 ⇒ 先别换（旧层留屏）\n}\n\n/**\n * 这一层现在是否还被\"切层内容闸门\"押着（`we-layer--pending`）。\n *\n * 为什么视频通道要知道：**换源会清掉已上屏的那一帧**。层还被押着时（旧壁纸在屏上）换源\n * 是免费的；层已经上屏后再换，屏上就只剩这一层的底色 —— 真机形态：设了「帧率上限」时，\n * 抽帧就绪那一刻在**在屏元素**上 `src = transcoded; load()` ⇒ 一块纯色（限制帧率才有、\n * 设成无限制就没有，正是这条）。所以升级只允许在 pending 期间落地，否则推到下一次建层\n * （见 buildVideoMedia 对 selection.transcodeReady 的使用）。\n */\nfunction layerStillPending() {\n  try {\n    const n = document.getElementById(LAYER_ID);\n    return Boolean(n && n.classList && typeof n.classList.contains === \"function\"\n      && n.classList.contains(\"we-layer--pending\"));\n  } catch { return false; }\n}\n\n/**\n * 视频档的媒体构建（③：自 src/media-prep.js 迁入）。\n *\n * 返回 `media`；Edge 那条腿（镜像画布）返回 `[media, canvas]`，由调用点用 `Array.isArray`\n * 识别。`fitClass` 是调用点所在函数的局部量 ⇒ 作为参数传入。\n */\nfunction buildVideoMedia(sel, fitClass) {\n  // 轮换领养：就绪元素（已 canplay/预播中）直接进层；已匹配的转码元素不重赋 src，\n  // 只有仍在原片且目标抽帧版已就绪时，才在建层阶段换源。\n  const prepared = consumePreparedMedia(\"VIDEO\", sel.url);\n  // 预热元素（见 VIDEO_WARM_TTL_MS 那段）：领养它 ⇒ 建层那一刻解复用器已经在位。\n  const warmed = prepared ? null : consumeWarmVideo(sel.url);\n  const media = prepared || warmed || document.createElement(\"video\");\n  const tok = String(sel.url || \"\").split(\"/\").pop();\n  const rc = selection.transcodeReady;\n  const useCached = Boolean(rc && rc.url && rc.fps === selection.fpsCap && rc.token === tok);\n  if ((!prepared && !warmed)\n      || (useCached && media.dataset.weTranscoded !== String(rc.fps))) {\n    // 已经转好的抽帧版（上一次在\"已上屏\"状态下就绪、刻意没换源的那一份）：\n    // **建层时就用它当 src** —— 这样整个生命周期里一次换源都不发生（换源 = 清掉当前帧 = 纯色）。\n    // 判据只看\"这份抽帧版是不是当前上限的\"：**不看原生可解性** —— 帧率上限的意义就是压解码\n    // 占用，原生可解的源照样可能帧率超标（4K120 的 H.264），拿它当免转条件会让上限在实际\n    // 在用的 mp4 上完全失效（见 capNeedsTranscode 的注释）。\n    media.src = useCached ? rc.url : sel.url;\n    if (useCached) {\n      try { media.dataset.weTranscoded = String(rc.fps); } catch { /* ignore */ }\n      selection.transcodeState = \"ready\";\n      selection.transcodeProgress = null;\n    }\n    // poster=预览图：覆盖初始加载与抽帧转码 swap 的空窗（原黑屏闪烁点）。\n    // 视频类壁纸**不设 WE 自带的 `preview.gif`** —— 动图当 poster 会\"先播预览、再停首帧、\n    // 最后进正片\"；改为**只认插件自己抽的静态缩略图**（`/video-preview/…` 是 ffmpeg 抽的一帧\n    // JPEG，见宿主 videoPreviewCachePath 的 `pv_*.jpg`）。挂上它有两重收益：\n    //   ① 切层内容闸门把 `video[poster]` 直接算作\"有画面\" ⇒ **立即放行**，不再等首帧\n    //     （等首帧实测会把整次切换推到十几秒：源越大 / 帧率上限越高越久）；\n    //   ② 加载窗口里屏上是**真缩略图**，而不是无帧 <video> 那块空/黑 ⇒ 闸门要防的\n    //     \"露出底色\"照旧不发生。\n    // 场景内嵌 MP4 的 poster 是静态帧，是「先静帧后动态」的既有设计，保留 —— 判据见\n    // rotation-prepared-leak-smoke.mjs 的 T2 / T2b（无静态缩略图仍必须等帧）。\n    const stillPreview = !!sel.previewUrl\n      && (sel.type !== \"video\" || /\\/video-preview\\//.test(sel.previewUrl));\n    if (stillPreview) media.poster = sel.previewUrl;\n  }\n  media.autoplay = true;\n  // 轮播「当前视频播完就换下一张」档（issue #230 后续）必须**关掉 loop** ——\n  // `loop` 会让元素循环播放、`ended` 永远不触发，那条轮换信号就发不出来。\n  // 其他档照旧 loop（壁纸单张循环是产品语义）。`activeRotationGroup` 在单文件 import\n  // 的沙箱里不存在 ⇒ 用 typeof 探，缺省按 loop 开（安全方向：不改变既有行为）。\n  media.loop = !(typeof activeRotationGroup === \"function\"\n    && (() => { const g = activeRotationGroup(); return Boolean(g) && g.trigger === \"videoEnd\"; })());\n  // ⚠️ 必须显式 `preload=\"auto\"`：缺省（=metadata）+ 这几张源的 moov 在文件**尾部** ⇒\n  // Chromium 取完 moov 就停，真正开始取帧要等 `play()` —— 而 play() 在**更晚的一趟**\n  // syncLayers 里才被调用（自动播放被策略拒绝时那一趟永远不会来）。真机日志（桌面壳）\n  // 里\"rs=0 停 2 秒\"正是这一段空窗；而元素从 loadedmetadata 到 presented 实测只要 ~110ms。\n  // auto 让元素**建层即开始取数据**（本地文件，代价可忽略）。\n  media.preload = \"auto\";\n  // 音轨按用户设置应用（见 weApplyAudio）：默认 0 音量 ⇒ 等价 muted；调高音量后才有声音。\n  media.setAttribute(\"playsinline\", \"\");\n  // Native playbackRate — hardware-decoded, instant, no reload.\n  try { media.playbackRate = sel.playbackRate; } catch { /* ignore */ }\n  if (IS_EDGE && sel.edgeCompat !== false) {\n    // Edge: keep the decoder element out of sight (its floating 下载/投屏\n    // toolbar attaches to any VISIBLE <video>), render via <canvas> instead\n    // (see weStartDraw / weDrawFrame). Attributes are belt-and-suspenders.\n    media.setAttribute(\"disablepictureinpicture\", \"\");\n    media.setAttribute(\"disableremoteplayback\", \"\");\n    media.style.cssText = \"position:absolute;left:-100000px;top:0;width:320px;height:180px;opacity:0.01;pointer-events:none;\";\n    const canvas = document.createElement(\"canvas\");\n    canvas.className = \"we-media we-media--canvas\" + fitClass;\n    canvas.style.background = \"#000\";\n    return [media, canvas];\n  }\n  // ⚠️ 这一行是**尺寸与 object-fit 的来源**（`.we-media` / `.we-media--fit`）。\n  // ⑧ 提取 `buildVideoMedia` 时我的切分器末端排他，把原分支**最后一行**切掉了 ⇒\n  // 视频元素拿不到类名 ⇒ 只显示左上角、占不满屏（实测回归）。判据见 verify-scene-live\n  // 的「两条腿都必须挂类名」。\n  media.className = \"we-media\" + fitClass;\n  return media;\n}\n\n\n// ══════════════════════════════════════════════════════════════════════════════\n\n\n// ══════════════════════════════════════════════════════════════════════════════\n// 抽帧换源链路（媒体信息探测 + 抽帧升级 + 元数据兜底 + 取消）\n//\n// 它**零实时引用**，所以整块住在视频通道里而不是拆去别处。\n// 不变量：本段的模块级绑定**没有任何顶层求值期读取** ⇒ 在内联清单里换位置不会撞 TDZ\n//（顶层读别的模块的 `const` 会撞，见 `CODE-STRUCTURE.md` §5 第 2 条）。\n// ══════════════════════════════════════════════════════════════════════════════\n/**\n * **源元数据探测 + 抽帧转码升级**的完整生命周期。\n *\n * 为什么单独一个文件：这是一条**有状态的生命周期**（探测 → 决策 → 进度轮询 → 落地/回退），\n * 其中同时有\"迟到响应必须作废\"\"换上限要打断旧请求\"\"15s 元数据兜底\"\"播完才换源\"四件\n * 容易互相踩的事，集中在一处才看得清它们彼此的约束。\n *\n * 契约（本文件是客户端程序的一部分，构建期由 scripts/build-client.mjs 内联进 bundle 的\n * 工厂作用域，\"外部作用域\"= 同一 prelude / src/client.js 的顶层。依赖是**机械清点**出来的）：\n *   selection                 ← 设置/选中项的唯一 store（读：type/url/fpsCap/…）\n *   LAYER_ID                  ← 壁纸层元素 id\n *   emit()                    ← 单向重渲染（本文件不直接碰 DOM 结构）\n *   isEffectivelyPlaying()    ← \"当前是否在播\"（换源前判断，避免打断播放）\n *   weDrawFrame()             ← 抓/重绘一帧（换源后立刻上屏）\n *   apiJson(path) / apiFetch(path)  ← src/api-client.js（宿主 API 唯一出入口；探测带 signal 透传）\n * 提供的入口：\n *   refreshMediaInfo(force)              读 /media-info，写 selection.mediaInfo（含\"源 fps ≤ 上限 ⇒ 无需转码\"）\n *                                        以及宿主只读回答的\"该上限的抽帧版已在盘上\"\n *                                        ⇒ 预置 selection.transcodeReady（下一次建层直接播抽帧版）\n *   maybeUpgradeToTranscoded(video, token) 决策并启动/落地抽帧转码（syncLayers 调用）\n *   transcodeUpgradeFailed(video, token)   转码失败回退（含 UI 文案）\n *   abortTranscodeUpgrade()              打断升级：清轮询 + 清兜底 timer + abort 请求\n *   invalidateMediaInfoProbe()           作废\"进行中\"的探测（迟到的响应不再写 selection）\n *   abortMediaInfoProbe()                断开探测的 AbortController（卸载用）\n *   revertTranscodedVideo(video)         把已换源的 <video> 退回原始源\n *   clearUpgradePoll() / clearUpgradeMeta()  仅供守卫单独取用（内部实现）\n *\n * 不变量：\n *   · 这三个字段的**状态机写入全部在本文件**：`selection.mediaInfo` / `transcodeState` /\n *     `transcodeProgress`。src/client.js 只允许在**换壁纸/切走**时把它们**复位**\n *     （`= null` / `= \"idle\"`，紧接着 abortTranscodeUpgrade() + refreshMediaInfo() 交接给本文件）\n *     —— 别处改写会绕过状态机，让\"旧请求的结果覆盖新请求\"重新变成可能。\n *     这条不是口号：test/verify-transcode-state.mjs 扫两个源文件核对它。\n *   · 自己的运行状态（两个探测/升级的 token、AbortController、两个 timer）**不外露**，只经入口操作。\n *   · 定时器与 AbortController 必须成对清理：卸载路径调用 abortTranscodeUpgrade() ——\n *     漏掉就是\"卸载后 500ms 轮询永久泄漏\"（真实缺陷）。\n *   · 本文件必须保持浏览器安全（无 import / require / Node API），且**不得有顶层可执行语句**\n *     —— 它会被内联到 bundle 顶部（早于 client.js 正文），顶层读 body 里的 const 会撞 TDZ。\n */\n\n// ── Source metadata + frame-skip transcode (抽帧转码) ────────────────────────\n// The decode-side fps cap (帧率上限) is implemented as a HOST re-encode, NOT as\n// playbackRate: playbackRate is a speed multiplier, so capping decode through\n// it would slow the motion. The host transcodes the wallpaper once to the cap\n// fps (4K120 → 4K60, timeline 1.0x, AV1 via NVENC) and caches it; here we play\n// the ORIGINAL immediately (instant first paint) and, while the host runs the\n// one-time transcode, swap to the capped-fps file when it is ready — normal\n// speed + halved decode. 倍速 (playbackRate) keeps working on top of either.\nlet mediaInfoToken = \"\";\n// In-flight marker: while the /media-info probe for this token is pending,\n// maybeUpgradeToTranscoded must NOT fire a transcode request — the probe may\n// come back with fps ≤ cap (no transcode needed). Without this guard every\n// wallpaper selection used to trigger a throwaway host-side ffmpeg run.\nlet mediaInfoInFlight = \"\";\n// 在途探测的 AbortController: token 变更或强制刷新时终止上一次 fetch — 否则被\n// 取代的探测会一直跑 (结果只靠 mediaInfoToken 检查丢弃), fiber 卸载时也要 abort。\nlet mediaInfoAbort = null;\n/**\n * 抽帧版的 URL（唯一构造点）：`maybeUpgradeToTranscoded` 的探针/换源与\n * `refreshMediaInfo` 采纳宿主\"已有缓存\"的回答都走它 —— 两处各拼一次字符串迟早漂移。\n */\nfunction transcodedUrlFor(token, fps) {\n  return \"/wallpaper-engine/transcoded/\" + encodeURIComponent(token) + \"?fps=\" + fps;\n}\nasync function refreshMediaInfo(force) {\n  const token = selection.type === \"video\" && selection.url\n    ? selection.url.split(\"/\").pop()\n    : null;\n  if (!token || (!force && token === mediaInfoToken)) return;\n  // 旧探测的结果一定没用了 (token 变了, 或被 force 重刷取代) → 立刻断开\n  if (mediaInfoAbort) { try { mediaInfoAbort.abort(); } catch { /* ignore */ } mediaInfoAbort = null; }\n  // AbortController 可能不存在 (无计时器/无 fetch 设施的验证环境): 为 null 时走无 abort 的退化路径\n  const ctrl = typeof AbortController === \"function\" ? new AbortController() : null;\n  mediaInfoAbort = ctrl;\n  mediaInfoToken = token;\n  mediaInfoInFlight = token;\n  try {\n    // 探测带 abort：`apiJson` 透传 signal，被取代的探测不写状态（下方 mediaInfoToken 校验）。\n    // `?fps=` 是**当前上限**：宿主据此只读地回答\"这个上限的抽帧版在不在盘上\"（见下）。\n    const res = await apiJson(\n      \"/media-info/\" + encodeURIComponent(token) + \"?fps=\" + encodeURIComponent(String(selection.fpsCap || 0)),\n      { signal: ctrl ? ctrl.signal : undefined });\n    const data = res.data || {};\n    if (mediaInfoToken === token && !(ctrl && ctrl.signal.aborted)) {\n      selection.mediaInfo = (data && data.info) || null;\n      // 源帧率**不高于**上限 ⇒ 不需要抽帧；把在途的升级停掉。\n      const mi = selection.mediaInfo;\n      if (capNeedsTranscode(mi, selection.fpsCap) === false) {\n        abortTranscodeUpgrade();\n        // Also drop a swapped transcode from a previous LOWER cap, so the\n        // panel hint matches what is actually playing (the original).\n        const layer = document.getElementById(LAYER_ID);\n        const video = layer && layer.querySelector(\"video\");\n        if (video && video.dataset.weTranscoded) revertTranscodedVideo(video);\n        selection.transcodeState = \"skipped\";\n      } else if (data.transcode && data.transcode.cached === true\n        && Number(data.transcode.fps) === Number(selection.fpsCap)) {\n        // 宿主确认这个上限的抽帧